export type QueueItem = { id: string; visible: boolean; priority: number };

export function selectVisible(items: QueueItem[]): QueueItem[] {
  return items.filter((item) => item.visible);
}

export type QueueItem = { id: string; visible: boolean; priority: number };

export function selectVisible(items: QueueItem[]): QueueItem[] {
  return items.filter((item) => item.visible).sort((a, b) => b.priority - a.priority);
}

